"use strict";(globalThis.webpackChunkjc_community_site=globalThis.webpackChunkjc_community_site||[]).push([[2076],{41385(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>r,default:()=>d,frontMatter:()=>a,metadata:()=>i,toc:()=>h});const i=JSON.parse('{"id":"general/break-fix-to-msp-3-msp-tools","title":"Break Fix To Msp 3 Msp Tools","description":"By JC-ChrisTate","source":"@site/docs/general/break-fix-to-msp-3-msp-tools.md","sourceDirName":"general","slug":"/general/break-fix-to-msp-3-msp-tools","permalink":"/jc-community-archive/general/break-fix-to-msp-3-msp-tools","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Break Fix To Msp 3 Msp Tools","description":"By JC-ChrisTate"},"sidebar":"docs","previous":{"title":"Break Fix To Msp 2 The Msp Mindset","permalink":"/jc-community-archive/general/break-fix-to-msp-2-the-msp-mindset"},"next":{"title":"Break Fix To Msp 4 Pricing","permalink":"/jc-community-archive/general/break-fix-to-msp-4-pricing"}}');var s=n(74848),o=n(28453);const a={title:"Break Fix To Msp 3 Msp Tools",description:"By JC-ChrisTate"},r=void 0,l={},h=[{value:"3. Let\u2019s Talk About Tools",id:"3-lets-talk-about-tools",level:3},{value:"Professional Services Automation (PSA)",id:"professional-services-automation-psa",level:3},{value:"Remote Monitoring &amp; Management (RMM)",id:"remote-monitoring--management-rmm",level:3}];function c(e){const t={h3:"h3",li:"li",p:"p",strong:"strong",ul:"ul",...(0,o.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(t.h3,{id:"3-lets-talk-about-tools",children:"3. Let\u2019s Talk About Tools"}),"\n",(0,s.jsx)(t.p,{children:"Welcome back to this short series about transitioning your business from a break-fix company to becoming an MSP.\xa0"}),"\n",(0,s.jsx)(t.p,{children:"Today I wanted to discuss the main two tools MSPs use and a little reasoning behind them. It may seem a little like putting the horse before the cart but it will all, hopefully, make sense."}),"\n",(0,s.jsx)(t.h3,{id:"professional-services-automation-psa",children:"Professional Services Automation (PSA)"}),"\n",(0,s.jsx)(t.p,{children:"In the world of MSPs, time really is money. Because of the fixed fee nature of the agreements it\u2019s vital that the MSP understands how much time is being spent on each client. This is where the PSA solution comes in and can help out.\xa0"}),"\n",(0,s.jsx)(t.p,{children:"Obviously functionality varies by PSA but the most common features are:"}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Ticketing"})}),"\n",(0,s.jsx)(t.p,{children:"The bread and butter of a PSA is ticketing, this is where all of the work the Service Desk carries out is recorded. Tickets can come from a variety of different sources such as:"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Manually entered"}),"\n",(0,s.jsx)(t.li,{children:"Client entered via ticketing portal"}),"\n",(0,s.jsx)(t.li,{children:"Automatically created via RMM (see below)"}),"\n",(0,s.jsx)(t.li,{children:"Automatically created via email"}),"\n",(0,s.jsx)(t.li,{children:"From within the PSA itself for automation purposes."}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"One of the main differences between ticketing in a PSA solution and a dedicated enterprise solution is that time is more of a concern. This is because in PSA solutions labor times can be attributed a monetary value and in turn this allows the MSP to understand the profitability of each client. We will delve into this further in a future post."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Contract Management"})}),"\n",(0,s.jsx)(t.p,{children:"PSAs also handle contract management, this is again so the MSP can understand things such as profitability. As an example, an MSP may take on a 50 user engineering company and they sign a Fixed Fee contract to support their users, servers and cloud applications. Having this agreement within the PSA ensures that the engineers know what is within the agreement and perhaps more importantly, what isn\u2019t. If a user calls in with a problem with their personal tablet, they wouldn\u2019t generally be part of the contract so any work on this would be invoiced separately."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Invoicing"})}),"\n",(0,s.jsxs)(t.p,{children:["MSPs generally generate their client invoices through their PSA solution. There is also the need for an accountancy package also, but these don\u2019t have to be MSP specific.",(0,s.jsx)(t.strong,{children:"Project Management"})]}),"\n",(0,s.jsx)(t.p,{children:"Most PSA solutions have Project Management capabilities. These are generally used for larger jobs that require multiple resources within the MSP."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Documentation Management"})}),"\n",(0,s.jsx)(t.p,{children:"Knowing details about the clients sites, such as IP addresses, serial numbers etc is vital in the day to day operations of an MSP. This is why most PSA solutions have functionality for this built in."}),"\n",(0,s.jsx)(t.p,{children:"Examples of PSA solutions include :"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Autotask PSA"}),"\n",(0,s.jsx)(t.li,{children:"ConnectWise Manage"}),"\n",(0,s.jsx)(t.li,{children:"Kaseya BSM"}),"\n",(0,s.jsx)(t.li,{children:"N-able MSP Manager"}),"\n",(0,s.jsx)(t.li,{children:"Syncro (Combined PSA/RMM)"}),"\n",(0,s.jsx)(t.li,{children:"Atera (Combined PSA/RMM)"}),"\n"]}),"\n",(0,s.jsx)(t.h3,{id:"remote-monitoring--management-rmm",children:"Remote Monitoring & Management (RMM)"}),"\n",(0,s.jsx)(t.p,{children:"After the PSA, the RMM solution is the next tool that most MSPs will use. They of course vary in functionality, but they are generally attempting to assist the MSP with several tasks."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Monitoring"})}),"\n",(0,s.jsx)(t.p,{children:"One of the primary purposes of an RMM is monitoring, this could be as simple as monitoring if a service fails or checking that disk space isn\u2019t too low. It could also be more involved around checking for problems within applications. These monitors can check indicators of things that may be about to cause an issue before they do, this allows the team to be proactive and resolve it before the end user is aware."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Alerting"})}),"\n",(0,s.jsx)(t.p,{children:"If something isn\u2019t right it\u2019s important that the RMM alerts the MSP about the issue. This is where the alerting comes in and it can be done in several ways. Firstly, all the RMM solutions will have some kind of dashboard where alerts will be highlighted, but this relies on someone monitoring these. They all also have the ability to create a support ticket from the alert. This means that when something goes wrong it will automatically appear in the task list for the Service Desk team."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Automation"})}),"\n",(0,s.jsx)(t.p,{children:"Automation is a key part of an RMMs functionality. It varies of course depending on the platform in use, but they will all have the capability to restart services that have stopped and initiate routines to clean up temporary files etc when the disk is getting full."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Patch Management"})}),"\n",(0,s.jsx)(t.p,{children:"This is a very time consuming task for MSPs and one that most RMMs can automate. This ensures that client machines are using the latest software and in turn this should reduce the amount of support tickets being generated."}),"\n",(0,s.jsx)(t.p,{children:(0,s.jsx)(t.strong,{children:"Remote Assist"})}),"\n",(0,s.jsx)(t.p,{children:"If something does go wrong, then it\u2019s common for the MSP to need to connect remotely to the clients PC or server. Most have built in remote assist capabilities to help with this, and there are several third party solutions also.\xa0"}),"\n",(0,s.jsx)(t.p,{children:"Examples of PSA solutions include :"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsx)(t.li,{children:"Datto RMM"}),"\n",(0,s.jsx)(t.li,{children:"ConnectWise Automate"}),"\n",(0,s.jsx)(t.li,{children:"N-able N-central"}),"\n",(0,s.jsx)(t.li,{children:"N-able RMM"}),"\n",(0,s.jsx)(t.li,{children:"Kaseya VSA"}),"\n",(0,s.jsx)(t.li,{children:"Syncro (Combined PSA/RMM)"}),"\n"]}),"\n",(0,s.jsx)(t.p,{children:"So, with a PSA and RMM solution in place the MSP has the foundations to become successful. There are obviously a lot more tools that are used within the MSP and also the client, but we will come to those in another update. There is no right or wrong PSA/RMM combination, speak to successful MSPs and see what works for them, trial several solutions and see what works best for you in your new MSP."}),"\n",(0,s.jsx)(t.p,{children:"Next time we will tackle that age old dilemma - how to price your services.\xa0"}),"\n",(0,s.jsx)(t.p,{children:"Until then, have a great week.\xa0"}),"\n",(0,s.jsx)(t.p,{children:"Chris"})]})}function d(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},28453(e,t,n){n.d(t,{R:()=>a,x:()=>r});var i=n(96540);const s={},o=i.createContext(s);function a(e){const t=i.useContext(o);return i.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);